import type {Dict} from '@/lib/i18n';
/** /setup/google-cloud, /connect and /privacy. `text` in backticks renders as code, **text** as bold. */

type Api='sc'|'ga4'|'admin'|'yt'|'yta'|'cal'|'gmail'|'drive'|'sheets'|'docs'|'ads';
export type GcpCopy={kicker:string;h1:string;lead:string;s1t:string;s1p:string;s1link:string;s2t:string;s2p:string;live:string;planned:string;open:string;api:Record<Api,string>;s3t:string;s3:[string,string,string];s4t:string;s4p:string;s4after:string;s5t:string;s5:[string,string];connect:string;s6t:string;s6p:string;dash:string;localT:string;localP:string;localLink:string;source:string};
export const gcpCopy:Dict<GcpCopy>={
 en:{kicker:'STEP-BY-STEP GUIDE',h1:'Use your own Google Cloud project',lead:'The remote CamMicGo MCP uses your own Google OAuth client (client ID and secret): Google API calls count only against your project’s quota. CamMicGo itself allows 100 calls per day and per account. No token to copy by hand.',s1t:'1. Create your Google Cloud project',s1p:'Sign in to Google Cloud Console and create a project you control. Check the project selector in the top bar before enabling APIs. The Google account that can access Search Console or Analytics may differ from the project owner.',s1link:'Open Google Cloud Console ↗',s2t:'2. Enable the APIs you need',s2p:'Open each link and click **Enable**. For CamMicGo tools: Search Console, Analytics Data, Analytics Admin, YouTube Data API v3 and Calendar. The others are optional for now.',live:'MCP tools available',planned:'Planned',open:'Open in Google Cloud ↗',api:{sc:'Search queries, clicks, CTR, impressions and positions.',ga4:'Traffic, countries and top pages. Also enable Analytics Admin.',admin:'Lists the GA4 properties you can access.',yt:'Search, channels, video details and playlists. Transcripts come from the CamMicGo apps.',yta:"Statistics of your own channels: views, watch time, retention, traffic sources and YouTube search terms.",cal:'Read-only calendars and events.',gmail:"Search and read your emails (read-only).",drive:"List, search and read your files. Writing is optional: new files only, trash after your confirmation.",sheets:'Planned; enabling the API alone adds no tool.',docs:'Planned; no dedicated MCP tool yet.',ads:'Not live yet. Keyword Planner needs approved Basic or Standard access.'},s3t:'3. Configure the consent screen',s3:['**Branding**: application name, support email and contact.','**Audience**: External, Testing mode, then add your Google account under Test users.','**Data access**: nothing mandatory; CamMicGo requests read-only scopes when you sign in.'],s4t:'4. Create a Web OAuth client',s4p:'In **Clients**, create an OAuth client of type **Web application** (not Desktop) and add this URI under **Authorized redirect URIs** (not JavaScript origins):',s4after:'Copy the **Client ID** (ending in `.apps.googleusercontent.com`) and the **Client secret**. Keep them in a password manager; never paste them into an AI chat or a public repository.',s5t:'5. Use them with CamMicGo',s5:['**On the website**: open My account (seo.cammicgo.com/account), sign in with your email, paste the project ID, client ID and secret, then click **Connect Google**.','**From Claude or ChatGPT**: the first time you connect the CamMicGo connector, the authorization window shows the same form.'],connect:'Connect Google ↗',s6t:'6. Check your quota',s6p:'In APIs & Services › Dashboard, check your project’s usage. Ask your assistant to run `service_info`: it should report “own Google Cloud project”. Google also applies per-user, per-site and per-property limits.',dash:'Open the API dashboard ↗',localT:'Using the local MCP server?',localP:'It uses a **Desktop** OAuth client instead and runs entirely on your computer.',localLink:'Local installation guide ↗',source:'Source and documentation ↗'},
 fr:{kicker:'GUIDE PAS À PAS',h1:'Utiliser votre propre projet Google Cloud',lead:'Le MCP distant CamMicGo utilise votre propre client OAuth Google (ID client et code secret) : les appels aux API Google ne sont décomptés que du quota de votre projet. CamMicGo autorise de son côté 100 appels par jour et par compte. Aucun jeton à copier à la main.',s1t:'1. Créez votre projet Google Cloud',s1p:'Connectez-vous à la console Google Cloud et créez un projet dont vous avez le contrôle. Vérifiez le sélecteur de projet en haut avant d’activer les API. Le compte Google qui accède à Search Console ou Analytics peut être différent du propriétaire du projet.',s1link:'Ouvrir la console Google Cloud ↗',s2t:'2. Activez les API nécessaires',s2p:'Ouvrez chaque lien et cliquez sur **Activer**. Pour les outils CamMicGo : Search Console, Analytics Data, Analytics Admin, YouTube Data API v3 et Agenda. Les autres sont optionnelles pour l’instant.',live:'Outils MCP disponibles',planned:'Prévu',open:'Ouvrir dans Google Cloud ↗',api:{sc:'Requêtes, clics, CTR, impressions et positions.',ga4:'Trafic, pays et pages principales. Activez aussi Analytics Admin.',admin:'Liste les propriétés GA4 auxquelles vous avez accès.',yt:'Recherche, chaînes, détails des vidéos et playlists. Les transcriptions viennent des applications CamMicGo.',yta:"Statistiques de vos propres chaînes : vues, durée de visionnage, rétention, sources de trafic et recherches YouTube.",cal:'Agendas et événements en lecture seule.',gmail:"Recherche et lecture de vos e-mails (lecture seule).",drive:"Lister, rechercher et lire vos fichiers. Écriture facultative : nouveaux fichiers uniquement, corbeille après votre confirmation.",sheets:'Prévu ; activer l’API seule n’ajoute aucun outil.',docs:'Prévu ; pas encore d’outil MCP dédié.',ads:'Pas encore disponible. Le Planificateur de mots clés exige un accès Basic ou Standard validé.'},s3t:'3. Configurez l’écran de consentement',s3:['**Branding** : nom de l’application, e-mail d’assistance et contact.','**Audience** : Externe, mode Test, puis ajoutez votre compte Google dans Utilisateurs test.','**Accès aux données** : rien d’obligatoire ; CamMicGo demande des autorisations en lecture seule à la connexion.'],s4t:'4. Créez un client OAuth Web',s4p:'Dans **Clients**, créez un client OAuth de type **Application Web** (pas Bureau) et ajoutez cet URI dans **URI de redirection autorisés** (pas dans les origines JavaScript) :',s4after:'Copiez l’**ID client** (se terminant par `.apps.googleusercontent.com`) et le **code secret du client**. Gardez-les dans un gestionnaire de mots de passe ; ne les collez jamais dans une conversation IA ou un dépôt public.',s5t:'5. Utilisez-les avec CamMicGo',s5:['**Sur le site** : ouvrez Mon compte (seo.cammicgo.com/account), connectez-vous avec votre e-mail, collez l’ID du projet, l’ID client et le code secret, puis cliquez sur **Connecter Google**.','**Depuis Claude ou ChatGPT** : la première fois que vous connectez le connecteur CamMicGo, la fenêtre d’autorisation affiche le même formulaire.'],connect:'Connecter Google ↗',s6t:'6. Vérifiez votre quota',s6p:'Dans API et services › Tableau de bord, consultez l’utilisation de votre projet. Demandez à votre assistant d’exécuter `service_info` : il doit indiquer « own Google Cloud project ». Google applique aussi des limites par utilisateur, par site et par propriété.',dash:'Ouvrir le tableau de bord des API ↗',localT:'Vous utilisez le serveur MCP local ?',localP:'Il utilise plutôt un client OAuth **Bureau** et fonctionne entièrement sur votre ordinateur.',localLink:'Guide d’installation locale ↗',source:'Code source et documentation ↗'},
 es:{kicker:'GUÍA PASO A PASO',h1:'Usa tu propio proyecto de Google Cloud',lead:'El MCP remoto de CamMicGo usa tu propio cliente OAuth de Google (ID y secreto): las llamadas a las APIs de Google solo cuentan contra la cuota de tu proyecto. CamMicGo permite 100 llamadas al día por cuenta. Sin tokens que copiar a mano.',s1t:'1. Crea tu proyecto de Google Cloud',s1p:'Inicia sesión en la consola de Google Cloud y crea un proyecto que controles. Revisa el selector de proyecto arriba antes de activar las APIs. La cuenta de Google con acceso a Search Console o Analytics puede ser distinta de la propietaria del proyecto.',s1link:'Abrir la consola de Google Cloud ↗',s2t:'2. Activa las APIs que necesites',s2p:'Abre cada enlace y pulsa **Habilitar**. Para las herramientas de CamMicGo: Search Console, Analytics Data, Analytics Admin, YouTube Data API v3 y Calendar. Las demás son opcionales por ahora.',live:'Herramientas MCP disponibles',planned:'Previsto',open:'Abrir en Google Cloud ↗',api:{sc:'Consultas, clics, CTR, impresiones y posiciones.',ga4:'Tráfico, países y páginas principales. Activa también Analytics Admin.',admin:'Lista las propiedades GA4 a las que tienes acceso.',yt:'Búsqueda, canales, detalles de vídeos y listas. Las transcripciones llegan desde las apps CamMicGo.',yta:"Estadísticas de tus propios canales: vistas, tiempo de visualización, retención, fuentes de tráfico y búsquedas en YouTube.",cal:'Calendarios y eventos en solo lectura.',gmail:"Búsqueda y lectura de tus correos (solo lectura).",drive:"Listar, buscar y leer tus archivos. Escritura opcional: solo archivos nuevos y papelera tras tu confirmación.",sheets:'Previsto; activar la API no añade herramientas.',docs:'Previsto; aún sin herramienta MCP dedicada.',ads:'Aún no disponible. El Planificador de palabras clave requiere acceso Basic o Standard aprobado.'},s3t:'3. Configura la pantalla de consentimiento',s3:['**Marca**: nombre de la aplicación, correo de asistencia y contacto.','**Público**: Externo, modo de prueba, y añade tu cuenta de Google en Usuarios de prueba.','**Acceso a los datos**: nada obligatorio; CamMicGo pide permisos de solo lectura al iniciar sesión.'],s4t:'4. Crea un cliente OAuth web',s4p:'En **Clientes**, crea un cliente OAuth de tipo **Aplicación web** (no de escritorio) y añade este URI en **URI de redireccionamiento autorizados** (no en orígenes de JavaScript):',s4after:'Copia el **ID de cliente** (termina en `.apps.googleusercontent.com`) y el **secreto de cliente**. Guárdalos en un gestor de contraseñas; nunca los pegues en un chat de IA ni en un repositorio público.',s5t:'5. Úsalos con CamMicGo',s5:['**En el sitio web**: abre Mi cuenta (seo.cammicgo.com/account), inicia sesión con tu correo, pega el ID del proyecto, el ID de cliente y el secreto, y pulsa **Conectar Google**.','**Desde Claude o ChatGPT**: la primera vez que conectas el conector CamMicGo, la ventana de autorización muestra el mismo formulario.'],connect:'Conectar Google ↗',s6t:'6. Comprueba tu cuota',s6p:'En APIs y servicios › Panel, revisa el uso de tu proyecto. Pide a tu asistente que ejecute `service_info`: debe indicar «own Google Cloud project». Google también aplica límites por usuario, sitio y propiedad.',dash:'Abrir el panel de APIs ↗',localT:'¿Usas el servidor MCP local?',localP:'Usa en su lugar un cliente OAuth de **escritorio** y funciona por completo en tu ordenador.',localLink:'Guía de instalación local ↗',source:'Código fuente y documentación ↗'},
 de:{kicker:'SCHRITT-FÜR-SCHRITT-ANLEITUNG',h1:'Eigenes Google-Cloud-Projekt verwenden',lead:'Der Remote-MCP von CamMicGo nutzt Ihren eigenen Google-OAuth-Client (Client-ID und Secret): Google-API-Aufrufe zählen nur gegen das Kontingent Ihres Projekts. CamMicGo selbst erlaubt 100 Aufrufe pro Tag und Konto. Kein Token zum Kopieren.',s1t:'1. Google-Cloud-Projekt erstellen',s1p:'Melden Sie sich in der Google Cloud Console an und erstellen Sie ein Projekt, das Sie kontrollieren. Prüfen Sie oben die Projektauswahl, bevor Sie APIs aktivieren. Das Google-Konto mit Zugriff auf Search Console oder Analytics kann vom Projektinhaber abweichen.',s1link:'Google Cloud Console öffnen ↗',s2t:'2. Benötigte APIs aktivieren',s2p:'Öffnen Sie jeden Link und klicken Sie auf **Aktivieren**. Für die CamMicGo-Tools: Search Console, Analytics Data, Analytics Admin, YouTube Data API v3 und Kalender. Die übrigen sind vorerst optional.',live:'MCP-Tools verfügbar',planned:'Geplant',open:'In Google Cloud öffnen ↗',api:{sc:'Suchanfragen, Klicks, CTR, Impressionen und Positionen.',ga4:'Traffic, Länder und Top-Seiten. Aktivieren Sie auch Analytics Admin.',admin:'Listet die GA4-Properties, auf die Sie Zugriff haben.',yt:'Suche, Kanäle, Videodetails und Playlists. Transkripte kommen von den CamMicGo-Apps.',yta:"Statistiken Ihrer eigenen Kanäle: Aufrufe, Wiedergabezeit, Zuschauerbindung, Traffic-Quellen und YouTube-Suchbegriffe.",cal:'Kalender und Termine, nur lesend.',gmail:"E-Mails suchen und lesen (nur Lesezugriff).",drive:"Dateien auflisten, suchen und lesen. Schreiben optional: nur neue Dateien, Papierkorb erst nach Ihrer Bestätigung.",sheets:'Geplant; die API allein fügt kein Tool hinzu.',docs:'Geplant; noch kein eigenes MCP-Tool.',ads:'Noch nicht verfügbar. Der Keyword-Planer erfordert genehmigten Basic- oder Standard-Zugriff.'},s3t:'3. Zustimmungsbildschirm einrichten',s3:['**Branding**: App-Name, Support-E-Mail und Kontakt.','**Zielgruppe**: Extern, Testmodus, dann Ihr Google-Konto unter Testnutzer hinzufügen.','**Datenzugriff**: nichts Pflicht; CamMicGo fordert bei der Anmeldung nur Lesebereiche an.'],s4t:'4. Web-OAuth-Client erstellen',s4p:'Erstellen Sie unter **Clients** einen OAuth-Client vom Typ **Webanwendung** (nicht Desktop) und fügen Sie diesen URI unter **Autorisierte Weiterleitungs-URIs** hinzu (nicht bei JavaScript-Quellen):',s4after:'Kopieren Sie die **Client-ID** (endet auf `.apps.googleusercontent.com`) und das **Client-Secret**. Bewahren Sie sie in einem Passwortmanager auf; fügen Sie sie nie in einen KI-Chat oder ein öffentliches Repository ein.',s5t:'5. Mit CamMicGo verwenden',s5:['**Auf der Website**: Öffnen Sie Mein Konto (seo.cammicgo.com/account), melden Sie sich mit Ihrer E-Mail an, fügen Sie Projekt-ID, Client-ID und Secret ein und klicken Sie auf **Google verbinden**.','**Aus Claude oder ChatGPT**: Beim ersten Verbinden des CamMicGo-Connectors zeigt das Autorisierungsfenster dasselbe Formular.'],connect:'Google verbinden ↗',s6t:'6. Kontingent prüfen',s6p:'Prüfen Sie unter APIs & Dienste › Dashboard die Nutzung Ihres Projekts. Lassen Sie Ihren Assistenten `service_info` ausführen: Er sollte „own Google Cloud project“ melden. Google wendet zusätzlich Limits pro Nutzer, Website und Property an.',dash:'API-Dashboard öffnen ↗',localT:'Sie nutzen den lokalen MCP-Server?',localP:'Er verwendet stattdessen einen **Desktop**-OAuth-Client und läuft vollständig auf Ihrem Computer.',localLink:'Anleitung zur lokalen Installation ↗',source:'Quellcode und Dokumentation ↗'},
 pt:{kicker:'GUIA PASSO A PASSO',h1:'Use seu próprio projeto Google Cloud',lead:'O MCP remoto da CamMicGo usa seu próprio cliente OAuth do Google (ID e segredo): as chamadas às APIs do Google contam só na cota do seu projeto. A CamMicGo permite 100 chamadas por dia por conta. Nenhum token para copiar à mão.',s1t:'1. Crie seu projeto Google Cloud',s1p:'Entre no console do Google Cloud e crie um projeto que você controla. Confira o seletor de projeto no topo antes de ativar APIs. A conta Google com acesso ao Search Console ou Analytics pode ser diferente da proprietária do projeto.',s1link:'Abrir o console do Google Cloud ↗',s2t:'2. Ative as APIs necessárias',s2p:'Abra cada link e clique em **Ativar**. Para as ferramentas CamMicGo: Search Console, Analytics Data, Analytics Admin, YouTube Data API v3 e Agenda. As demais são opcionais por enquanto.',live:'Ferramentas MCP disponíveis',planned:'Previsto',open:'Abrir no Google Cloud ↗',api:{sc:'Consultas, cliques, CTR, impressões e posições.',ga4:'Tráfego, países e páginas principais. Ative também o Analytics Admin.',admin:'Lista as propriedades GA4 a que você tem acesso.',yt:'Pesquisa, canais, detalhes de vídeos e playlists. As transcrições vêm dos apps CamMicGo.',yta:"Estatísticas dos seus próprios canais: visualizações, tempo de exibição, retenção, fontes de tráfego e pesquisas no YouTube.",cal:'Agendas e eventos somente leitura.',gmail:"Pesquisa e leitura dos seus e-mails (somente leitura).",drive:"Listar, pesquisar e ler seus arquivos. Gravação opcional: só arquivos novos, lixeira após sua confirmação.",sheets:'Previsto; ativar a API sozinha não adiciona ferramenta.',docs:'Previsto; ainda sem ferramenta MCP dedicada.',ads:'Ainda não disponível. O Planejador de palavras-chave exige acesso Basic ou Standard aprovado.'},s3t:'3. Configure a tela de consentimento',s3:['**Branding**: nome do app, e-mail de suporte e contato.','**Público-alvo**: Externo, modo de teste, e adicione sua conta Google em Usuários de teste.','**Acesso a dados**: nada obrigatório; a CamMicGo pede escopos somente leitura no login.'],s4t:'4. Crie um cliente OAuth da Web',s4p:'Em **Clientes**, crie um cliente OAuth do tipo **Aplicativo da Web** (não Desktop) e adicione este URI em **URIs de redirecionamento autorizados** (não em origens JavaScript):',s4after:'Copie o **ID do cliente** (termina em `.apps.googleusercontent.com`) e o **Segredo do cliente**. Guarde-os num gerenciador de senhas; nunca os cole em conversas de IA ou repositórios públicos.',s5t:'5. Use-os com a CamMicGo',s5:['**No site**: abra Minha conta (seo.cammicgo.com/account), entre com seu e-mail, cole o ID do projeto, o ID do cliente e o segredo e clique em **Conectar o Google**.','**Pelo Claude ou ChatGPT**: na primeira vez que você conecta o conector CamMicGo, a janela de autorização mostra o mesmo formulário.'],connect:'Conectar Google ↗',s6t:'6. Verifique sua cota',s6p:'Em APIs e serviços › Painel, confira o uso do seu projeto. Peça ao assistente para executar `service_info`: ele deve indicar «own Google Cloud project». O Google também aplica limites por usuário, site e propriedade.',dash:'Abrir o painel de APIs ↗',localT:'Usa o servidor MCP local?',localP:'Ele usa um cliente OAuth do tipo **Desktop** e roda inteiramente no seu computador.',localLink:'Guia de instalação local ↗',source:'Código-fonte e documentação ↗'},
 it:{kicker:'GUIDA PASSO PASSO',h1:'Usa il tuo progetto Google Cloud',lead:'L’MCP remoto di CamMicGo usa il tuo client OAuth Google (ID client e secret): le chiamate alle API Google pesano solo sulla quota del tuo progetto. CamMicGo consente 100 chiamate al giorno per account. Nessun token da copiare a mano.',s1t:'1. Crea il tuo progetto Google Cloud',s1p:'Accedi alla console Google Cloud e crea un progetto che controlli. Controlla il selettore di progetto in alto prima di attivare le API. L’account Google con accesso a Search Console o Analytics può essere diverso dal proprietario del progetto.',s1link:'Apri la console Google Cloud ↗',s2t:'2. Attiva le API necessarie',s2p:'Apri ogni link e fai clic su **Abilita**. Per gli strumenti CamMicGo: Search Console, Analytics Data, Analytics Admin, YouTube Data API v3 e Calendar. Le altre per ora sono facoltative.',live:'Strumenti MCP disponibili',planned:'Previsto',open:'Apri in Google Cloud ↗',api:{sc:'Query, clic, CTR, impressioni e posizioni.',ga4:'Traffico, paesi e pagine principali. Attiva anche Analytics Admin.',admin:'Elenca le proprietà GA4 a cui hai accesso.',yt:'Ricerca, canali, dettagli video e playlist. Le trascrizioni arrivano dalle app CamMicGo.',yta:"Statistiche dei tuoi canali: visualizzazioni, tempo di visualizzazione, fidelizzazione, sorgenti di traffico e ricerche su YouTube.",cal:'Calendari ed eventi in sola lettura.',gmail:"Ricerca e lettura delle email (sola lettura).",drive:"Elencare, cercare e leggere i tuoi file. Scrittura facoltativa: solo nuovi file, cestino dopo la tua conferma.",sheets:'Previsto; attivare la sola API non aggiunge strumenti.',docs:'Previsto; ancora nessuno strumento MCP dedicato.',ads:'Non ancora disponibile. Keyword Planner richiede un accesso Basic o Standard approvato.'},s3t:'3. Configura la schermata di consenso',s3:['**Branding**: nome dell’app, email di assistenza e contatto.','**Pubblico**: Esterno, modalità test, poi aggiungi il tuo account Google tra gli Utenti di test.','**Accesso ai dati**: nulla di obbligatorio; CamMicGo chiede ambiti in sola lettura all’accesso.'],s4t:'4. Crea un client OAuth web',s4p:'In **Client**, crea un client OAuth di tipo **Applicazione web** (non desktop) e aggiungi questo URI in **URI di reindirizzamento autorizzati** (non nelle origini JavaScript):',s4after:'Copia l’**ID client** (termina con `.apps.googleusercontent.com`) e il **client secret**. Conservali in un gestore di password; non incollarli mai in una chat IA o in un repository pubblico.',s5t:'5. Usali con CamMicGo',s5:['**Sul sito**: apri Il mio account (seo.cammicgo.com/account), accedi con la tua email, incolla ID progetto, ID client e secret, poi fai clic su **Collega Google**.','**Da Claude o ChatGPT**: la prima volta che colleghi il connettore CamMicGo, la finestra di autorizzazione mostra lo stesso modulo.'],connect:'Collega Google ↗',s6t:'6. Controlla la quota',s6p:'In API e servizi › Dashboard, controlla l’utilizzo del progetto. Chiedi all’assistente di eseguire `service_info`: deve indicare «own Google Cloud project». Google applica anche limiti per utente, sito e proprietà.',dash:'Apri la dashboard delle API ↗',localT:'Usi il server MCP locale?',localP:'Usa invece un client OAuth **Desktop** e funziona interamente sul tuo computer.',localLink:'Guida all’installazione locale ↗',source:'Codice sorgente e documentazione ↗'},
 ru:{kicker:'ПОШАГОВОЕ РУКОВОДСТВО',h1:'Используйте собственный проект Google Cloud',lead:'Удалённый MCP CamMicGo использует ваш собственный клиент OAuth Google (Client ID и секрет): вызовы API Google расходуют только квоту вашего проекта. CamMicGo разрешает 100 вызовов в день на аккаунт. Никаких токенов вручную.',s1t:'1. Создайте проект Google Cloud',s1p:'Войдите в консоль Google Cloud и создайте проект под своим контролем. Перед включением API проверьте выбор проекта вверху. Аккаунт Google с доступом к Search Console или Analytics может отличаться от владельца проекта.',s1link:'Открыть консоль Google Cloud ↗',s2t:'2. Включите нужные API',s2p:'Откройте каждую ссылку и нажмите **Включить**. Для инструментов CamMicGo: Search Console, Analytics Data, Analytics Admin, YouTube Data API v3 и Календарь. Остальные пока необязательны.',live:'Инструменты MCP доступны',planned:'Запланировано',open:'Открыть в Google Cloud ↗',api:{sc:'Запросы, клики, CTR, показы и позиции.',ga4:'Трафик, страны и популярные страницы. Включите также Analytics Admin.',admin:'Список ресурсов GA4, к которым у вас есть доступ.',yt:'Поиск, каналы, сведения о видео и плейлисты. Расшифровки приходят из приложений CamMicGo.',yta:"Статистика ваших каналов: просмотры, время просмотра, удержание аудитории, источники трафика и поисковые запросы YouTube.",cal:'Календари и события только для чтения.',gmail:"Поиск и чтение писем (только чтение).",drive:"Список, поиск и чтение файлов. Запись по желанию: только новые файлы, корзина после вашего подтверждения.",sheets:'Запланировано; само включение API инструментов не добавляет.',docs:'Запланировано; отдельного инструмента MCP пока нет.',ads:'Пока недоступно. Для Планировщика ключевых слов нужен одобренный доступ Basic или Standard.'},s3t:'3. Настройте экран согласия',s3:['**Брендинг**: название приложения, адрес поддержки и контакт.','**Аудитория**: Внешняя, тестовый режим, затем добавьте свой аккаунт Google в тестовые пользователи.','**Доступ к данным**: ничего обязательного; CamMicGo запрашивает только права чтения при входе.'],s4t:'4. Создайте веб-клиент OAuth',s4p:'В разделе **Клиенты** создайте клиент OAuth типа **Веб-приложение** (не «Компьютер») и добавьте этот URI в **Разрешённые URI перенаправления** (не в источники JavaScript):',s4after:'Скопируйте **Client ID** (оканчивается на `.apps.googleusercontent.com`) и **секрет клиента**. Храните их в менеджере паролей; никогда не вставляйте их в чаты с ИИ или публичные репозитории.',s5t:'5. Используйте их в CamMicGo',s5:['**На сайте**: откройте «Мой аккаунт» (seo.cammicgo.com/account), войдите по e-mail, вставьте ID проекта, Client ID и секрет и нажмите **Подключить Google**.','**Из Claude или ChatGPT**: при первом подключении коннектора CamMicGo окно авторизации показывает ту же форму.'],connect:'Подключить Google ↗',s6t:'6. Проверьте квоту',s6p:'В разделе API и сервисы › Панель управления посмотрите использование проекта. Попросите ассистента выполнить `service_info`: должно быть указано «own Google Cloud project». Google также применяет лимиты на пользователя, сайт и ресурс.',dash:'Открыть панель API ↗',localT:'Используете локальный MCP-сервер?',localP:'Он использует клиент OAuth типа **Компьютер** и работает полностью на вашем компьютере.',localLink:'Руководство по локальной установке ↗',source:'Исходный код и документация ↗'},
 zh:{kicker:'分步指南',h1:'使用你自己的 Google Cloud 项目',lead:'CamMicGo 远程 MCP 使用你自己的 Google OAuth 客户端（客户端 ID 和密钥）：Google API 调用只计入你项目的配额。CamMicGo 本身每个账户每天允许 100 次调用。无需手动复制任何令牌。',s1t:'1. 创建 Google Cloud 项目',s1p:'登录 Google Cloud 控制台，创建一个由你控制的项目。启用 API 前，请检查顶部的项目选择器。能访问 Search Console 或 Analytics 的 Google 账号可以与项目所有者不同。',s1link:'打开 Google Cloud 控制台 ↗',s2t:'2. 启用所需的 API',s2p:'打开每个链接并点击 **启用**。CamMicGo 工具需要：Search Console、Analytics Data、Analytics Admin、YouTube Data API v3 和日历。其他暂为可选。',live:'MCP 工具可用',planned:'计划中',open:'在 Google Cloud 中打开 ↗',api:{sc:'搜索查询、点击、点击率、展示次数和排名。',ga4:'流量、国家/地区和热门页面。还需启用 Analytics Admin。',admin:'列出你可以访问的 GA4 媒体资源。',yt:'搜索、频道、视频详情和播放列表。字幕来自 CamMicGo 应用。',yta:"你自己频道的统计数据：观看次数、观看时长、观众留存、流量来源和 YouTube 搜索词。",cal:'只读的日历和活动。',gmail:"搜索和阅读你的邮件（只读）。",drive:"列出、搜索和读取你的文件。写入为可选：仅新建文件，移入回收站前需你确认。",sheets:'计划中；仅启用 API 不会增加工具。',docs:'计划中；暂无专用 MCP 工具。',ads:'尚未上线。关键字规划师需要已获批的 Basic 或 Standard 访问权限。'},s3t:'3. 配置同意屏幕',s3:['**品牌塑造**：应用名称、支持邮箱和联系方式。','**受众群体**：外部、测试模式，然后在测试用户中添加你的 Google 账号。','**数据访问**：无必填项；CamMicGo 在登录时只请求只读范围。'],s4t:'4. 创建 Web OAuth 客户端',s4p:'在 **客户端** 中创建类型为 **Web 应用** 的 OAuth 客户端（不是桌面应用），并在 **已获授权的重定向 URI** 中添加以下 URI（不是 JavaScript 来源）：',s4after:'复制 **客户端 ID**（以 `.apps.googleusercontent.com` 结尾）和 **客户端密钥**。请保存在密码管理器中；切勿粘贴到 AI 对话或公开代码库。',s5t:'5. 在 CamMicGo 中使用',s5:['**在网站上**：打开“我的账户”（seo.cammicgo.com/account），用邮箱登录，粘贴项目 ID、客户端 ID 和密钥，然后点击 **连接 Google**。','**从 Claude 或 ChatGPT**：首次连接 CamMicGo 连接器时，授权窗口会显示同样的表单。'],connect:'连接 Google ↗',s6t:'6. 检查配额',s6p:'在“API 和服务 › 信息中心”查看项目用量。让助手运行 `service_info`：应显示“own Google Cloud project”。Google 还会按用户、网站和媒体资源施加限制。',dash:'打开 API 信息中心 ↗',localT:'在用本地 MCP 服务器？',localP:'它改用 **桌面** 类型的 OAuth 客户端，完全在你的电脑上运行。',localLink:'本地安装指南 ↗',source:'源代码和文档 ↗'},
 ja:{kicker:'手順ガイド',h1:'自分の Google Cloud プロジェクトを使う',lead:'CamMicGo のリモート MCP は、あなた自身の Google OAuth クライアント（クライアント ID とシークレット）を使います。Google API の呼び出しはあなたのプロジェクトの割り当てだけを消費します。CamMicGo 側の上限は 1 アカウント 1 日 100 回です。トークンを手でコピーする必要はありません。',s1t:'1. Google Cloud プロジェクトを作成',s1p:'Google Cloud コンソールにログインし、自分が管理するプロジェクトを作成します。API を有効にする前に上部のプロジェクト選択を確認してください。Search Console や Analytics にアクセスできる Google アカウントは、プロジェクトのオーナーと異なっていてもかまいません。',s1link:'Google Cloud コンソールを開く ↗',s2t:'2. 必要な API を有効化',s2p:'各リンクを開き **有効にする** をクリックします。CamMicGo のツールには Search Console、Analytics Data、Analytics Admin、YouTube Data API v3、カレンダーが必要です。その他は現時点では任意です。',live:'MCP ツール利用可',planned:'予定',open:'Google Cloud で開く ↗',api:{sc:'検索クエリ、クリック、CTR、表示回数、掲載順位。',ga4:'トラフィック、国、上位ページ。Analytics Admin も有効にしてください。',admin:'アクセスできる GA4 プロパティを一覧表示。',yt:'検索、チャンネル、動画の詳細、再生リスト。文字起こしは CamMicGo アプリから取得。',yta:"自分のチャンネルの統計：視聴回数、総再生時間、視聴者維持率、トラフィック ソース、YouTube の検索語句。",cal:'カレンダーと予定（読み取り専用）。',gmail:"メールの検索と閲覧（読み取り専用）。",drive:"ファイルの一覧・検索・閲覧。書き込みは任意：新規ファイルのみ、ゴミ箱への移動は確認後。",sheets:'予定。API を有効にしてもツールは増えません。',docs:'予定。専用 MCP ツールは未提供。',ads:'未提供。キーワード プランナーには承認済みの Basic または Standard アクセスが必要です。'},s3t:'3. 同意画面を設定',s3:['**ブランディング**: アプリ名、サポートメール、連絡先。','**対象**: 外部・テストモードにし、テストユーザーに自分の Google アカウントを追加。','**データアクセス**: 必須項目なし。CamMicGo はサインイン時に読み取り専用スコープのみ求めます。'],s4t:'4. ウェブ OAuth クライアントを作成',s4p:'**クライアント** で種類が **ウェブ アプリケーション**（デスクトップではない）の OAuth クライアントを作成し、**承認済みのリダイレクト URI**（JavaScript 生成元ではない）に次の URI を追加します:',s4after:'**クライアント ID**（末尾が `.apps.googleusercontent.com`）と **クライアント シークレット** をコピーします。パスワードマネージャーに保管し、AI チャットや公開リポジトリには貼らないでください。',s5t:'5. CamMicGo で使う',s5:['**ウェブサイトで**: マイアカウント（seo.cammicgo.com/account）を開き、メールでサインインして、プロジェクト ID・クライアント ID・シークレットを貼り付け、**Google と接続** をクリックします。','**Claude や ChatGPT から**: CamMicGo コネクタを初めて接続するとき、認可画面に同じフォームが表示されます。'],connect:'Google と接続 ↗',s6t:'6. 割り当てを確認',s6p:'「API とサービス › ダッシュボード」でプロジェクトの使用量を確認します。アシスタントに `service_info` を実行してもらい、「own Google Cloud project」と表示されれば OK です。Google はユーザー・サイト・プロパティごとの上限も適用します。',dash:'API ダッシュボードを開く ↗',localT:'ローカル MCP サーバーをお使いですか？',localP:'こちらは **デスクトップ** 型の OAuth クライアントを使い、すべてパソコン上で動作します。',localLink:'ローカルインストールガイド ↗',source:'ソースコードとドキュメント ↗'},
 ko:{kicker:'단계별 가이드',h1:'내 Google Cloud 프로젝트 사용하기',lead:'CamMicGo 원격 MCP는 내 Google OAuth 클라이언트(클라이언트 ID와 시크릿)를 사용합니다. Google API 호출은 내 프로젝트 할당량에서만 차감되며, CamMicGo 자체 한도는 계정당 하루 100회입니다. 토큰을 직접 복사할 필요가 없습니다.',s1t:'1. Google Cloud 프로젝트 만들기',s1p:'Google Cloud 콘솔에 로그인해 직접 관리하는 프로젝트를 만드세요. API를 사용 설정하기 전에 상단의 프로젝트 선택기를 확인하세요. Search Console이나 Analytics에 접근하는 Google 계정은 프로젝트 소유자와 달라도 됩니다.',s1link:'Google Cloud 콘솔 열기 ↗',s2t:'2. 필요한 API 사용 설정',s2p:'각 링크를 열고 **사용**을 누르세요. CamMicGo 도구에는 Search Console, Analytics Data, Analytics Admin, YouTube Data API v3, 캘린더가 필요합니다. 나머지는 지금은 선택 사항입니다.',live:'MCP 도구 사용 가능',planned:'예정',open:'Google Cloud에서 열기 ↗',api:{sc:'검색어, 클릭수, CTR, 노출수, 순위.',ga4:'트래픽, 국가, 인기 페이지. Analytics Admin도 사용 설정하세요.',admin:'접근 가능한 GA4 속성 목록.',yt:'검색, 채널, 동영상 세부 정보, 재생목록. 자막은 CamMicGo 앱에서 가져옵니다.',yta:"내 채널 통계: 조회수, 시청 시간, 시청 지속률, 트래픽 소스, YouTube 검색어.",cal:'읽기 전용 캘린더와 일정.',gmail:"이메일 검색 및 읽기(읽기 전용).",drive:"파일 목록 보기, 검색, 읽기. 쓰기는 선택 사항: 새 파일만, 휴지통 이동은 확인 후.",sheets:'예정, API만 사용 설정해도 도구는 추가되지 않음.',docs:'예정, 전용 MCP 도구는 아직 없음.',ads:'아직 제공되지 않음. 키워드 플래너는 승인된 Basic 또는 Standard 액세스가 필요.'},s3t:'3. 동의 화면 구성',s3:['**브랜딩**: 앱 이름, 지원 이메일, 연락처.','**대상**: 외부, 테스트 모드로 설정하고 테스트 사용자에 내 Google 계정을 추가.','**데이터 액세스**: 필수 항목 없음. CamMicGo는 로그인 시 읽기 전용 범위만 요청합니다.'],s4t:'4. 웹 OAuth 클라이언트 만들기',s4p:'**클라이언트**에서 유형이 **웹 애플리케이션**(데스크톱 아님)인 OAuth 클라이언트를 만들고 **승인된 리디렉션 URI**(JavaScript 원본 아님)에 다음 URI를 추가하세요:',s4after:'**클라이언트 ID**(`.apps.googleusercontent.com`으로 끝남)와 **클라이언트 시크릿**을 복사하세요. 비밀번호 관리자에 보관하고 AI 대화나 공개 저장소에 붙여 넣지 마세요.',s5t:'5. CamMicGo에서 사용하기',s5:['**웹사이트에서**: 내 계정(seo.cammicgo.com/account)을 열고 이메일로 로그인한 뒤 프로젝트 ID, 클라이언트 ID, 시크릿을 붙여 넣고 **Google 연결**을 누르세요.','**Claude나 ChatGPT에서**: CamMicGo 커넥터를 처음 연결할 때 승인 창에 같은 양식이 표시됩니다.'],connect:'Google 연결 ↗',s6t:'6. 할당량 확인',s6p:'API 및 서비스 › 대시보드에서 프로젝트 사용량을 확인하세요. 어시스턴트에게 `service_info`를 실행해 달라고 하면 “own Google Cloud project”가 표시되어야 합니다. Google은 사용자·사이트·속성별 한도도 적용합니다.',dash:'API 대시보드 열기 ↗',localT:'로컬 MCP 서버를 사용하나요?',localP:'로컬 서버는 **데스크톱** 유형 OAuth 클라이언트를 사용하며 전부 내 컴퓨터에서 실행됩니다.',localLink:'로컬 설치 가이드 ↗',source:'소스 코드 및 문서 ↗'},
 ar:{kicker:'دليل خطوة بخطوة',h1:'استخدم مشروعك الخاص في Google Cloud',lead:'يستخدم خادم CamMicGo MCP البعيد عميل Google OAuth الخاص بك (المعرّف والسر): تُحتسب استدعاءات واجهات Google من حصة مشروعك فقط. وتسمح CamMicGo من جهتها بـ 100 استدعاء يوميًا لكل حساب. لا رموز لنسخها يدويًا.',s1t:'1. أنشئ مشروع Google Cloud',s1p:'سجّل الدخول إلى وحدة تحكم Google Cloud وأنشئ مشروعًا تتحكم فيه. تحقق من محدد المشروع في الأعلى قبل تفعيل الواجهات. يمكن أن يختلف حساب Google الذي يصل إلى Search Console أو Analytics عن مالك المشروع.',s1link:'فتح وحدة تحكم Google Cloud ↗',s2t:'2. فعّل الواجهات التي تحتاجها',s2p:'افتح كل رابط وانقر **تفعيل**. لأدوات CamMicGo: Search Console وAnalytics Data وAnalytics Admin وYouTube Data API v3 والتقويم. الباقي اختياري حاليًا.',live:'أدوات MCP متاحة',planned:'مخطط له',open:'فتح في Google Cloud ↗',api:{sc:'الاستعلامات والنقرات ونسبة النقر ومرات الظهور والمراكز.',ga4:'الزيارات والبلدان وأهم الصفحات. فعّل أيضًا Analytics Admin.',admin:'يسرد مواقع GA4 التي يمكنك الوصول إليها.',yt:'البحث والقنوات وتفاصيل الفيديو وقوائم التشغيل. تأتي التفريغات من تطبيقات CamMicGo.',yta:"إحصاءات قنواتك: المشاهدات ومدة المشاهدة والاحتفاظ بالجمهور ومصادر الزيارات وعبارات البحث في YouTube.",cal:'التقاويم والأحداث للقراءة فقط.',gmail:"البحث في بريدك الإلكتروني وقراءته (قراءة فقط).",drive:"عرض ملفاتك والبحث فيها وقراءتها. الكتابة اختيارية: ملفات جديدة فقط، والنقل إلى المهملات بعد تأكيدك.",sheets:'مخطط له؛ تفعيل الواجهة وحده لا يضيف أداة.',docs:'مخطط له؛ لا أداة MCP مخصصة بعد.',ads:'غير متاح بعد. يتطلب مخطط الكلمات الرئيسية وصولًا Basic أو Standard معتمدًا.'},s3t:'3. اضبط شاشة الموافقة',s3:['**العلامة التجارية**: اسم التطبيق وبريد الدعم وجهة الاتصال.','**الجمهور**: خارجي، وضع الاختبار، ثم أضف حساب Google الخاص بك ضمن مستخدمي الاختبار.','**الوصول إلى البيانات**: لا شيء إلزامي؛ تطلب CamMicGo نطاقات للقراءة فقط عند تسجيل الدخول.'],s4t:'4. أنشئ عميل OAuth للويب',s4p:'في **العملاء** أنشئ عميل OAuth من نوع **تطبيق ويب** (وليس سطح المكتب) وأضف هذا العنوان ضمن **عناوين URI المعتمدة لإعادة التوجيه** (وليس أصول JavaScript):',s4after:'انسخ **معرّف العميل** (ينتهي بـ `.apps.googleusercontent.com`) و**سر العميل**. احفظهما في مدير كلمات المرور؛ ولا تلصقهما أبدًا في محادثة ذكاء اصطناعي أو مستودع عام.',s5t:'5. استخدمهما مع CamMicGo',s5:['**على الموقع**: افتح حسابي (seo.cammicgo.com/account)، وسجّل الدخول ببريدك، والصق معرّف المشروع ومعرّف العميل والسر، ثم انقر **ربط Google**.','**من Claude أو ChatGPT**: عند ربط موصل CamMicGo أول مرة تعرض نافذة التفويض النموذج نفسه.'],connect:'ربط Google ↗',s6t:'6. تحقق من حصتك',s6p:'في الواجهات والخدمات › لوحة التحكم راجع استخدام مشروعك. اطلب من مساعدك تشغيل `service_info`: يجب أن يعرض «own Google Cloud project». يطبّق Google أيضًا حدودًا لكل مستخدم وموقع وخاصية.',dash:'فتح لوحة الواجهات ↗',localT:'تستخدم خادم MCP المحلي؟',localP:'يستخدم بدلًا من ذلك عميل OAuth من نوع **سطح المكتب** ويعمل بالكامل على حاسوبك.',localLink:'دليل التثبيت المحلي ↗',source:'الشيفرة المصدرية والتوثيق ↗'},
};

